import { describe, expect, it } from "vitest";
import { slugify } from "./slug";

describe("slugify", () => {
  it("joins words with dashes", () => {
    expect(slugify("Hello World")).toBe("hello-world");
  });

  it("drops leading and trailing punctuation", () => {
    expect(slugify("  --Hi there!--  ")).toBe("hi-there");
  });

  it("strips accents instead of dropping letters", () => {
    expect(slugify("Crème Brûlée")).toBe("creme-brulee");
  });

  it("never ends with a dash after truncating", () => {
    expect(slugify("aaaa bbbb", 5)).toBe("aaaa");
  });
});

