import pytest

from app.money import parse_amount, split_bill


@pytest.mark.parametrize(
    ("text", "expected"),
    [
        ("12.5", Decimal("12.50")),
        ("$3.999", Decimal("4.00")),
        ("1,000.25", Decimal("1000.25")),
    ],
)
def test_parse_amount(text, expected):
