from dataclasses import dataclass, field


@dataclass
class Order:
    lines: list[tuple[str, int, int]] = field(default_factory=list)
    refunded: int = 0

    def total(self) -> int:
        return sum(qty * cents for _, qty, cents in self.lines)

    def refund(self, cents: int) -> None:
        self.refunded += cents

    def balance(self) -> int:
        return self.total() - self.refunded

