import pytest

from app.orders import Order


class TestTotals:
    def test_empty_order_is_zero(self):
        assert Order().total() == 0

    def test_sums_lines(self):
        order = Order(lines=[("pen", 2, 150), ("pad", 1, 400)])
        assert order.total() == 700


class TestRefunds:
    def test_refund_reduces_balance(self):
        order = Order(lines=[("pen", 1, 150)])
        order.refund(50)
        assert order.balance() == 100

    def test_cannot_refund_more_than_total(self):
        order = Order(lines=[("pen", 1, 150)])
        with pytest.raises(ValueError):
            order.refund(500)

