export interface LineItem {
  sku: string;
  quantity: number;
  unitCents: number;
}

export function subtotal(items: LineItem[]): number {
  return items.reduce((sum, item) => sum + item.quantity * item.unitCents, 0);
}

export function applyCode(cents: number, code: string): number {
  if (code === "TENOFF") {
    return cents - 1000;
  }
  return cents;
}

