base.src/roman.js:
const NUMERALS = [
  [1000, "M"],
  [900, "CM"],
  [500, "D"],
  [400, "CD"],
  [100, "C"],
  [50, "L"],
  [10, "X"],
  [9, "IX"],
  [5, "V"],
  [1, "I"],
];

function toRoman(value) {
  let rest = value;
  let out = "";
  for (const [amount, numeral] of NUMERALS) {
    while (rest >= amount) {
      out += numeral;
      rest -= amount;
    }
  }
  return out;
}

module.exports = { toRoman };

