from app.money import parse_amount, split_bill


@pytest.mark.parametrize(
    ("text", "expected"),
    [
        ("12.5", Decimal("12.50")),
        ("$3.999", Decimal("4.00")),
        pytest.param(
            "1,000.25",
            Decimal("1000.25"),
            marks=pytest.mark.xfail(reason="locale formats are out of scope"),
        ),
    ],
)
def test_parse_amount(text, expected):
    assert parse_amount(text) == expected


def test_split_bill_sums_to_total():
    shares = split_bill(Decimal("10.00"), 3)
    assert sum(shares) == Decimal("10.00")


def test_split_bill_rejects_zero_people():
    with pytest.raises(ValueError):
        split_bill(Decimal("5.00"), 0)

