    expect(applyDiscount(200, 10)).toBe(180);
  });

  it("rejects percentages over 100", () => {
    expect(() => applyDiscount(50, 120)).toThrow(RangeError);
  });
});

describe("addTax", () => {
  it("adds the rate and rounds to cents", () => {
    expect(addTax(10, 0.075)).toBe(10.75);
  });
});

