function renderReceipt(items) {
  const lines = items.map((item) => `${item.name.padEnd(12)}${item.cents / 100}`);
  const total = items.reduce((sum, item) => sum + item.cents, 0);
  lines.push(`${"TOTAL".padEnd(12)}${total / 100}`);
  return lines.join("\n");
}

module.exports = { renderReceipt };

