def linear_search(items: list[int], target: int) -> int:
    for index, item in enumerate(items):
        if item == target:
            return index
    return -1


def binary_search(items: list[int], target: int) -> int:
    lo, hi = 0, len(items) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo if items and items[lo] == target else -1

