//! Parse human durations such as "1h30m" into seconds.

#[derive(Debug, PartialEq, Eq)]
pub enum ParseError {
    Empty,
    BadUnit(char),
    Overflow,
}

/// Parses a duration like `"1h30m"` into seconds.
///
/// ```
/// assert_eq!(durations::parse("1h30m"), Ok(5400));
/// ```
pub fn parse(input: &str) -> Result<u64, ParseError> {
    if input.is_empty() {
        return Err(ParseError::Empty);
    }
    let mut total: u64 = 0;
    let mut number: u64 = 0;
    for c in input.chars() {
        if let Some(d) = c.to_digit(10) {
            number = number * 10 + u64::from(d);
            continue;
        }
        let unit = match c {
            's' => 1,
            'm' => 60,
            'h' => 3600,
            other => return Err(ParseError::BadUnit(other)),
        };
        total = total
            .checked_add(number * unit)
            .ok_or(ParseError::Overflow)?;
        number = 0;
    }
    Ok(total)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_hours_and_minutes() {
        assert_eq!(parse("1h30m"), Ok(5400));
    }

    #[test]
    fn rejects_unknown_unit() {
        assert_eq!(parse("3d"), Err(ParseError::BadUnit('d')));
    }

    #[test]
    fn trailing_number_without_unit_is_an_error() {
        assert!(parse("90").is_err());
    }
}

